# t78 — redesign mobile (≤900px): cabeçalho, hero, ordem da Visão, acordeão de oportunidades, planilha recolhida, sem rolagem lateral, desktop inalterado
import sys; sys.path.insert(0, '/home/claude/test')
from t40_lib import *
A, errs = open_h('qa.t78@totvs.com.br')
A.evaluate("UI.view='importar'; render()"); A.wait_for_timeout(300)
A.set_input_files('#f-cart', D + 'carteira.xlsx'); A.wait_for_timeout(500); A.click('[data-a=impPrev]'); A.wait_for_timeout(300); A.click('[data-a=impGo]'); A.wait_for_timeout(3000)
# desktop inalterado
A.set_viewport_size({'width': 1440, 'height': 900}); ev(A, "UI.view='geral'; render()"); A.wait_for_timeout(1000)
ck('desktop: sem hero', ev(A, "!document.querySelector('.mhero')") or ev(A, "getComputedStyle(document.querySelector('.mhero')).display")=='none')
ck('desktop: cabeçalho claro (sem gradiente petróleo)', ev(A, "getComputedStyle(document.querySelector('.top')).backgroundImage")=='none')
ck('desktop: oportunidades sem acordeão', ev(A, "UI.view='oport'; render(); !document.querySelector('.mo-tg')"))
# mobile
A.set_viewport_size({'width': 390, 'height': 844}); ev(A, "UI.view='geral'; render()"); A.evaluate('window.scrollTo(0,0)'); A.wait_for_timeout(1000)
ck('mobile: cabeçalho petróleo em gradiente', 'gradient' in ev(A, "getComputedStyle(document.querySelector('.top')).backgroundImage"))
ck('mobile: busca no cabeçalho continua funcional (≥44px)', ev(A, "document.querySelector('#gq').getBoundingClientRect().height")>=44)
h = ev(A, "(()=>{const m=document.querySelector('.mhero');return m?{t:m.textContent,y:Math.round(m.getBoundingClientRect().top),chips:m.querySelectorAll('.mh-chip').length}:null})()")
print(h)
ck('mobile: hero com MRR informado e 2 atalhos', h and 'R$ 49.000,50' in h['t'].replace('\xa0', ' ') and h['chips'] == 2)
ck('mobile: hero logo abaixo do cabeçalho', h and h['y'] < 260)
ordem = ev(A, "[...document.querySelectorAll('#app>*')].filter(e=>getComputedStyle(e).display!=='none').sort((a,b)=>a.getBoundingClientRect().top-b.getBoundingClientRect().top).slice(0,4).map(e=>e.id||e.className.split(' ')[0])")
print(ordem)
ck('mobile: ordem hero → … → "Onde vale aprofundar" antes dos KPIs', ordem[0] == 'mhero' and ev(A, "document.querySelector('#hoje').getBoundingClientRect().top<document.querySelector('.kpi-strip').getBoundingClientRect().top"))
A.click('.mh-chip.pri'); A.wait_for_timeout(600)
ck('mobile: atalho do hero abre Oportunidades', ev(A, "UI.view") == 'oport')
A.evaluate('window.scrollTo(0,0)'); A.wait_for_timeout(400)
ck('mobile: oportunidades recolhidas por padrão', ev(A, "document.querySelectorAll('.card.opc .opp.mo-c').length")>0 and ev(A, "getComputedStyle(document.querySelector('.card.opc .opp table.chain')).display")=='none')
A.click('.card.opc .mo-tg'); A.wait_for_timeout(300)
ck('mobile: acordeão expande e mostra evidências', ev(A, "getComputedStyle(document.querySelector('.card.opc .opp.open table.chain')).display")!='none' and ev(A, "document.querySelector('.card.opc .mo-tg').getAttribute('aria-expanded')")=='true')
ck('mobile: botões de leitura mantidos no card recolhido', ev(A, "!!document.querySelector('.card.opc .opp .jd [data-a]')"))
ck('mobile: sem rolagem lateral nas Oportunidades', ev(A, "document.documentElement.scrollWidth<=innerWidth"))
ev(A, "UI.view='clientes'; render()"); A.wait_for_timeout(800)
ck('mobile: planilha do Google recolhida', ev(A, "getComputedStyle(document.querySelector('#shcard.shc-c form, #shcard.shc-c .row:nth-child(2)')||document.body).display")!='' and ev(A, "document.querySelector('#shcard').getBoundingClientRect().height")<130)
A.click('.shc-tg'); A.wait_for_timeout(300)
ck('mobile: "Configurar" expande a planilha', ev(A, "document.querySelector('#shcard').getBoundingClientRect().height")>200)
ck('mobile: sem rolagem lateral nos Clientes', ev(A, "document.documentElement.scrollWidth<=innerWidth"))
ev(A, "UI.confirm='csauto'; typeof renderModal==='function'&&renderModal()")
ck('sem erros de página', not errs)
print('FAILS', F)
